def fullqualname_py3(obj):
    """Fully qualified name for objects in Python 3."""
    if hasattr(obj, '__module__'):
        module = obj.__module__
        if module is None:
            module = '__main__'
        return module + '.' + obj.__qualname__
    else:
        return obj.__name__

